def evaluate_token_bucket(capacity: float, refill_rate: float, refill_period: float, current_tokens: float, last_refill_time: float, request_time: float, cost: float = 1.0) -> tuple[bool, float, float]:
    """Evaluates token bucket rate limit request, refills tokens based on elapsed time, and returns (allowed, remaining, new_last_refill)."""
    if capacity <= 0 or refill_rate <= 0 or refill_period <= 0 or cost <= 0:
        raise ValueError("Bucket parameters and cost must be positive numbers.")

    elapsed = max(0.0, request_time - last_refill_time)
    tokens_to_add = (elapsed / refill_period) * refill_rate
    refilled_tokens = min(capacity, current_tokens + tokens_to_add)

    if refilled_tokens >= cost:
        return (True, refilled_tokens - cost, request_time)
    else:
        return (False, refilled_tokens, request_time)

