    """Transitions circuit breaker state between CLOSED, OPEN, and HALF_OPEN based on failures, timeout, and call outcome.
    Returns (new_state, new_failure_count, new_last_failure_time).
    """
    valid_states = {"CLOSED", "OPEN", "HALF_OPEN"}
