def merge_overlapping_intervals(intervals: list[tuple[int, int]]) -> list[tuple[int, int]]:
    """Merges a list of half-open intervals [start, end) into non-overlapping contiguous intervals.
    Touching intervals [a, b) and [b, c) are merged into [a, c).
    """
    valid_intervals = [i for i in intervals if i[0] < i[1]]
    if not valid_intervals:
        return []
    sorted_intervals = sorted(valid_intervals, key=lambda x: (x[0], x[1]))
    merged = [sorted_intervals[0]]
    for current_start, current_end in sorted_intervals[1:]:
        last_start, last_end = merged[-1]
        if current_start <= last_end:
            merged[-1] = (last_start, max(last_end, current_end))
        else:
            merged.append((current_start, current_end))
    return merged

