from urllib.parse import unquote
from typing import Tuple

def split_host_port(raw_hostport: str) -> Tuple[str, str]:
    if not raw_hostport or not isinstance(raw_hostport, str):
        return "", ""
    hp = unquote(raw_hostport.strip())
    if "@" in hp:
        hp = hp.split("@", 1)[1]
    if hp.startswith("["):
        m = re.match(r"^\[(.+?)\](?::(\d+))?$", hp)
        if m:
            return m.group(1), (m.group(2) or "")
    if hp.count(":") > 1:
        return hp, ""
    if ":" in hp:
        h, p = hp.rsplit(":", 1)
        return h, p
    return hp, ""

