def detect_dag_cycle_and_ancestors(nodes: list[str], edges: list[tuple[str, str]]) -> tuple[bool, dict[str, set[str]]]:
    """Traverses directed graph to detect cycles and compute all reachable ancestors for each node.
    edges: list of (parent, child).
    Returns (has_cycle: bool, ancestors_dict: dict[str, set[str]]).
    """
    adj = defaultdict(list)
    in_degree = {n: 0 for n in nodes}
    parents = defaultdict(set)

    for u, v in edges:
        if u in in_degree and v in in_degree:
            adj[u].append(v)
            in_degree[v] += 1
            parents[v].add(u)

    queue = deque([n for n in nodes if in_degree[n] == 0])
    visited_count = 0
    ancestors = {n: set() for n in nodes}

    while queue:
        curr = queue.popleft()
        visited_count += 1
        for nxt in adj[curr]:
            ancestors[nxt].add(curr)
            ancestors[nxt].update(ancestors[curr])
            in_degree[nxt] -= 1
            if in_degree[nxt] == 0:
                queue.append(nxt)

    has_cycle = (visited_count != len(nodes))
    return (has_cycle, ancestors)

